// Only the MyTopicAvro declaration is generated by scripts/generate_kafka.ts.
// Source: "MyTopic.json"
import { fromAvro, type AvroSchema } from '@afcms/avro-zod';
import type { output } from 'zod/v4/core';

export const MyTopicAvro = {
  type: 'record',
  name: 'Event',
  namespace: 'demo',
  fields: [
    {
      name: 'id',
      type: 'long',
    },
    {
      name: 'status',
      type: {
        type: 'enum',
        name: 'Status',
        symbols: ['NEW', 'DONE'],
      },
    },
    {
      name: 'note',
      type: ['null', 'string'],
      default: null,
    },
    {
      name: 'timestamp',
      type: {
        type: 'long',
        logicalType: 'timestamp-millis',
      },
      default: 0,
    },
  ],
} as const satisfies AvroSchema;
export const MyTopicSchema = fromAvro(MyTopicAvro);
export type MyTopic = output<typeof MyTopicSchema>;

// Edit these factories by hand. Each is evaluated for every send, including presets.
export const MyTopicGeneratedParameters = {
  timestamp: () => BigInt(Date.now()),
} satisfies {
  [K in keyof MyTopic]?: () => MyTopic[K];
};
